"min": 10,
"reglas": [
"Se pondrán 7 o más aros dispersos en toda la cancha, un compañero será el tiburón.",
"Los demás compañeros serán los peces y estarán caminando por toda la cancha, sin meterse al aro.",
"Cuando el maestro avisa con voz fuerte ¡AHÍ VIENE EL TIBURÓN!",
"Todos los peces deberán correr al refugio (aros), pero solo tres puede haber tres peces por aro, así que los que están fuera del aro podrán ser capturados por el tiburón.",
"El docente podrá quitar aros en cada ronda."
],
