"min": 10,
"reglas": [
"En equipos con la misma cantidad de integrantes en cada uno, formados en la misma distancia, al sonido del silbato saldrá corriendo el primero de cada fila hasta rodear el cono que tenga enfrente, cuando regrese a su fila le dará la mano a su compañero que siga en la fila y los dos sin soltarse harán el mismo recorrido, y así sucesivamente hasta con el último integrante de su equipo, logrando llegar incluso antes que los demás."
],
