"El docente narra el cuento «El ratón, ratoncito» y asigna a un equipo el papel de «ratón» y al otro el de «ratoncito».",
"Cuando en el cuento se nombra a uno de los animales, ese equipo corre a atrapar al otro.",
"Se puede jugar en filas, enfrentándose uno a uno, o por tiempo, contando cuántos atrapa cada equipo.",
"A quienes sean atrapados se les pone un reto motor."
