"reglas": [
"Cada alumno con una pelota, realiza las siguientes acciones motrices: Girar la pelota con las dos manos.",
"Caminar por toda la cancha conduciendo la pelota, a la señal cambiar de pie.",
"Caminar, trotar y correr rodando la pelota con las manos, al silbatazo cambiar de mano.",
"Lanzar la pelota e intentar atraparla, etc."
],
