"min": 10,
"reglas": [
"Se divide la clase en dos grupos que se sitúan uno enfrente del otro en cada uno de los extremos de la cancha.",
"El grupo A bailara al ritmo que ellos elijan, el grupo B escoge su música.",
"Si suena el ritmo del A se desplazan bailando hacia el grupo B, pero si en el trayecto la música se apaga, entonces deberán de correr a su extremo para que el B no los atrape, los atraparan solo tocando a su compañero en alguna parte del cuerpo.",
"Lo mismo ocurrirá con el ritmo contrario."
],
