"mat": [
"conos",
"costalitos"
],
"min": 10,
"reglas": [
"En equipos cada uno se coloca en un extremo de la cancha formado en hileras.",
"Al extremo contrario se colocan conos frente a los equipos.",
"Cada uno de éstos tendrá un costalito; a la señal el primero de cada hilera deberá de tomar el costalito y salir corriendo al otro extremo realizando alguna consigna con el costalito (llevarlo entre las piernas sin que caiga, llevarla como mesero, etc.), regresa y le grita a su compañero: ¡ya! y repite la acción.",
"Gana el equipo que primero pasen todos sus integrantes."
],
