"mat": [
"botellas"
],
"min": 10,
"reglas": [
"Equipos de 8 colocados en hilera de 4 a unos 2-3 mts uno de otro, todos llevarán una botella pequeña de agua vacía excepto el primero que la llevará llena.",
"A la señal el primero de cada equipo saldrá hasta llegar al segundo y echará el agua en la botella del compañero y rápidamente saldrá corriendo hasta el final de la hilera.",
"El segundo realizará el mismo ejercicio y así sucesivamente.",
"El equipo que consiga llegar antes a la línea de llegada y con mayor cantidad de agua en su botella será el ganador."
],
