"hab": [],
"plano": "circulo",
"mat": [],
"min": 10,
"reglas": [
"De pie en círculo los niños se toman de las manos y a una señal corren a agruparse en medio del círculo.",
"A otra señal, retroceden para hacer el círculo lo mayor posible.",
"Además de variar las velocidades de desplazamiento (Robot, humano y leopardo) también se puede ir cambiando el tipo de desplazamiento: a la pata coja, con los ojos cerrados, de espaldas, de puntillas tomados de las manos, etc.",
"El círculo no debe romperse; pierde el equipo que se le rompa más veces su círculo."
],
