"mat": [
"costalitos"
],
"min": 10,
"reglas": [
"De manera individual, se colocan en la línea de inicio colocando un costalito en su cabeza.",
"El objetivo es llevar el costalito a la línea final sin que este se caiga y sin tocarlo con las manos.",
"Cada que logren llegar a la línea final deberán regresar corriendo para intentarlo de nuevo, pero ahora colocándolo en otra parte del cuerpo. (por equipos o individual dependiendo de los costalitos con que se cuente)."
],
