"min": 10,
"reglas": [
"Juego por parejas; dos niños se colocarán frente a frente cogidos de las manos, sirviéndose mutuamente de apoyo en las distintas posturas de equilibrio: levantar un pie y después el otro colocarse a distintas alturas e intentar girar.",
"Posteriormente, intentarlo soltando una mano y después la otra; apoyándose sobre la espalda, buscar distintas formas de equilibrarse, levantando sucesivamente los pies, con los brazos entrelazados con el compañero."
],
