"Los ositos al mismo tiempo le preguntarán a su \"papá\", papá oso, papá oso ¿nos dejas acercar al monstruo? y él les contestó; si pero solo cinco pasos, y entonces los ositos caminaran al mismo tiempo los cinco pasos y luego se detendrán para preguntar otra vez, papá oso, papá oso ¿nos dejas acercar al monstruo? y así seguirán preguntando hasta que el papá oso les diga no porque ahí viene, entonces los osos correrán hacia el papá oso, y el niño que sea TOCADO pasará a ayudarle al monstruo para atrapar más osos."
