"El vigilante se encontrará de espaldas hacia ellos y en ese momento las estatuas avanzarán hacia él, pero en el momento en el que se voltee de inmediato se detendrán y permanecerán inmóviles, si alguno de ellos se mueve o avanza, el vigilante lo nombra desde su lugar y este pasa a la línea desde donde empezó a avanzar.",
