"Al sonido del silbato saldrá el primero de cada fila y tomará el platillo con las manos y poniéndolo por fuera a un lado del aro, irá con el siguiente hacer lo mismo y con todos lo que están en su fila.",
"Al final habrá un un aro con pelota, se coloca dentro del aro y hará un lanzamiento, si logra derribar uno o más conos se los llevara a su equipo y esto les contará como punto si no derriba ninguno solo deja la pelota en su lugar y se regresará corriendo, la chocará con su compañero siguiente y saldrá a hacer lo mismo, solo que ahora, le tocará meter los platillos al aro.",
