"Así hasta llegar a donde el docente indique; regresa corriendo, se la da a su compañero y sale a hacer lo mismo. *Ahora irán realizando con dos aros, únicamente podrán avanzar estando dentro de un aro y moviendo el otro con la mano o buscando alguna estrategia, pero en todo momento dentro del aro.",
