"min": 10,
"reglas": [
"Los jugadores formados en dos equipos (rosado y blanco).",
"En el espacio de juego se colocan 3 colchonetas formando un triángulo, separadas 5 metros cada una, al centro de la figura geométrica se coloca un cono.",
"El equipo rosado se forma atrás del cono y el blanco se dispersa en el área de juego.",
"A la señal un blanco lanza la pelota de playa y la patea un alumno rosado, posteriormente corre a acostarse en una de las colchonetas.",
"Los blancos tienen que atrapar la pelota para eliminarlo o recogerla y lanzarla para pegarle.",
"Si un alumno rosa se acuesta en las tres colchonetas es un punto para el equipo.",
"Cuando todos patean se cambian los roles con el otro equipo."
],
