"reglas": [
"El profesor organizará grupos de 8 alumnos donde uno de los alumnos será la víctima.",
"Cada equipo tendrá que realizar tantos trayectos de 9 m como integrantes tenga el grupo.",
"Así, todos experimentarán ser la víctima o accidentado.",
"El transporte se hará con el accidentado en decúbito supino y a la altura de la cintura de la siguiente forma: Uno en la cabeza, uno a cada lado del tronco, a la altura de los hombros, uno en zona lumbar, dos en la zona de la pierna y dos en los pies."
],
