"Los alumnos se amarran las manos con un paliacate una encima de la otra y se forman atrás de la línea.",
"A la señal los alumnos toman una pelota de la caja y lanzan la pelota rodándola por el suelo con dirección a los bolos.",
"Gana el equipo que primero derribe todos."
