"min": 10,
"reglas": [
"Uno de los jugadores se acostará en una colchoneta (1 por cada grupo de 3-4 alumnos).",
"Inicialmente deberá estar completamente relajado como si estuviera dormido.",
"Sus compañeros, dispuestos a ambos lados, intentarán levantarle hasta dejarle de pie.",
"Después de 2-3 intentos con cada alumno, el que está tumbado ahora realizará una potente contracción muscular, como si fuera el tronco de un árbol.",
"Sus compañeros le colocarán de pie mediante una acción explosiva, teniendo en todo momento los pies por debajo de la cabeza."
],
