"hab": [],
"plano": "filas",
"mat": [],
"min": 10,
"reglas": [
"Cada equipo se coloca frente a una fila de bancas de madera y al otro lado se encuentran dispersos por el suelo todo tipo de objetos.",
"El juego consiste en ver qué equipo es capaz de acumular más tesoros y para ello cada uno de sus miembros de uno en uno camina por encima de las bancas y regresará con un sólo objeto procurando no caerse al precipicio.",
"Si se cae deberá dejar el tesoro y empezar de nuevo."
],
