"En cada una un equipo; se distribuyen varias pelotas al centro en la línea que divide los campos.",
"El objetivo es lanzar pelotas contra el equipo contrario.",
"Si una pelota impacta sobre algún jugador este deberá tumbarse con piernas y brazos extendidos.",
"Volverá a jugar si dos compañeros, uno de cada brazo lo arrastran hasta el final de su campo (hospital) donde podrá levantarse y volver a jugar.",
"Una pelota solo puede tomarse si previamente bota en el suelo.",
"Tendrá cada equipo 3 cañones: el equipo dice stop y los rivales se quedan quietos y lanzan una pelota de playa rodando y a quien le pegue se acuesta. | Colchoneta Material variado Conos pelotas."
