"Estos últimos intentaran cruzar por entre la zona central destinada para el otro equipo sin ser tocados por el filtro, si son tocados formaran parte del filtro, si no son tocados podrán pasar cuantas veces puedan.",
"Gana el último que no es tocado por el filtro."
