"min": 15,
"reglas": [
"Se dividira al grupo en pequeños equipos, los cuales se colocaran en fila detrás de un cono, al silbatazo realizaran la consigna asiganda (puede ser zigzag sobre conos, saltos con un pie, pies juntos, ranitas), al terminar el ejercicio correran a a un aro situado delante de todos los equipo (el cual tiene fichas o tapitas), el primero que llegue tomara una ficha y la pondra enfrente del cono de su equipo, en cada turno solo el primero que llegue al aro sera el que pueda tomar una ficha, al terminar las fichas del aro, ganara el equipo que haya formado el puente mas largo con las tapitas."
],
