"Un integrante de la pareja marca un pulso constante con el pandero (o las maracas) y lo hace coincidir con su desplazamiento; el compañero le copia de manera simultánea.",
"Debe ser un ritmo que aumenta o disminuye la velocidad a la indicación del profesor o cuando lo acuerden los alumnos.",
