"Luego, cada uno escoge un número, que pintará al extremo contrario del patio, de tal manera que cada quien aporte un dato para resolver la operación o la palabra previamente seleccionada; por ejemplo, se le dice al equipo “la suma que, como resultado, dé , si el equipo tiene cinco integrantes, cada uno por turnos en relevo, corre a plasmar el número para lograr la suma que como resultado dé “2”.",
"Comenzar con cifras, operaciones y palabras fáciles, aclarar que deben realizar una operación o palabra entre todos, no cada uno por su lado.",
