"reglas": [
"El profesor va dando consignas a la vez que un diciendo “soy un muñeco muy divertido” y me gusta mover los… (Dedos, manos, etc.)”.",
"Todos los alumnos repiten la frase y mueven la parte del cuerpo que se ha mencionado.",
"A continuación, se dice “soy un muñeco divertido y me gusta mover los dedos y las muñecas” y los niños repiten en voz alta y con movimientos.",
"De este modo se van añadiendo partes corporales siguiendo una dirección lógica; codos, hombros, cuello, cintura, rodillas, tobillos, hasta terminar diciendo “soy muñeco muy divertido y me gusta mover el cuerpo”."
],
