"Los jugadores se sitúan en la línea con una botella que deben lanzar, inicialmente, a meter en el redondel número uno, y posteriormente al resto.",
"Si el lanzamiento cae dentro del aro, se debe ir saltando con un pie hasta donde está la botella y de ahí lanzar al siguiente aro, solo saltara si el lanzamiento es bueno, si no da el turno."
