"El pueblo dice que los bajamos; el pueblo dice que levantamos un pie.",
"Lo bajamos; saltamos sobre un pie; si la frase no va precedida de El pueblo dice, no se hace lo indicado.",
"Quien se equivoque es la persona que dirá lo que el pueblo dice."
