"reglas": [
"Cada jugador se sitúa con un balón personal enfrente de una pared, a unos 6 m de separación.",
"Él mismo se pondrá de acuerdo para dar una señal y chutar su respectiva botella, con la intención de lanzar la propia a la pared y ésta rebote. | Material apilable Pañuelo Pelotas Botellas."
],
