"reglas": [
"En un área delimitada, se ponen seis porterías con ayuda de algunos conos (alrededor del espacio); se designa a un alumno en cada portería que defenderá y a la vez tratará de anotar en la portería de sus adversarios.",
"Se coloca una pelota al centro del área para iniciar el juego.",
"De manera previa, y en distintas pausas a lo largo del juego se permite a los alumnos diseñar su estrategia."
],
"gr": [
4
],
"fases": [
4
],
"de": "Profra. Elisa Paola Camacho Cruz"
