"reglas": [
"Los alumnos con la pelota en su cesta; corren hasta llegar a un punto donde se envía un pase a la pared; ésta debe rebotar hasta el punto de lanzamiento.",
"Si la pelota no llega a la fila, el jugador en turno debe aproximarse, introducir la pelota en su cesta sin tocarla con la mano y volver a la fila desde donde continúa."
],
