"plano": "dispersos",
"mat": [
"pelotas",
"colchonetas"
],
"min": 10,
"reglas": [
"Individualmente, cada uno con colchoneta (escudos) para defenderse y con pelotas de esponja (flechas) para meter en sus bolsas.",
"Ellos mismos intentarán lanzarse las flechas para que reboten en las colchonetas para cubrirse todo el cuerpo.",
"Si logran golpearse pierden unos segundos y tienen que colocar su colchoneta en el piso y sentarse.",
"Puede regresar al juego si un compañero dice su nombre."
],
