"En un campo delimitado previamente por conos, se escogen a 2 o 3 alumnos del grupo que la hacen de perro, van a cuadrupedia persiguiendo al resto de los jugadores que se desplazan a la pata coja.",
"Cuando alguien es mordido (atrapado), les contagian la rabia y se convierten en perro y los ayudan a morder a los restantes.",
"El juego finaliza cuando todos son perros rabiosos."
