"min": 10,
"reglas": [
"Los jugadores se desplazan elevando rodillas, talones, moviendo los brazos, de puntillas, rotando el tronco, aplaudiendo, alegres, enojados, corriendo, etc.",
"Cuando la maestra diga “Esculturas de carne y hueso” deberán quedarse inmóviles.",
"A la señal regresan a moverse; se puede realizar con alumnos tomados de las manos o todo el grupo hacer una sola escultura."
],
