"mat": [],
"min": 10,
"reglas": [
"Colocamos varias bancas, unas al lado de las otras, todos los niños se suben encima; el maestro les explica que deben colocarse según el día de nacimiento y sin bajar de la banca primero el niño que sea mayor después el segundo, el tercero, etc., entonces los niños van diciéndose unos a otros la fecha de nacimiento y van cambiando de lugar, hasta que queden ordenados de mayor a menor edad."
],
