"est": "Juego motor",
"hab": [],
"plano": "parejas",
"mat": [
"cuerdas"
],
"min": 10,
"reglas": [
"Dividido el alumnado en parejas se colocan uno al frente y el otro atrás.",
"El primero debe flexionar la pierna que él quiera y su compañero agarrarla con la mano o con una cuerda corta.",
"En esta posición deberán de desplazarse coordinando los movimientos en todo momento para evitar caerse o soltarse.",
"Cuando esto sucede deberán de esperar a que otra pareja los ayude formando ahora 4 flamencos.",
"Se sigue el juego hasta que todo el grupo queda unido en un flamenco gigante."
],
"gr": [
4
],
"fases": [
4
],
