"reglas": [
"Todos los alumnos se colocan estirando el paracaídas, a la señal del docente comienzan a bajar hasta sentarse en el suelo sin tocarle con las manos tomando el paracaídas como soporte.",
"Una vez logrado se repite igual para levantarse."
],
