"mat": [],
"min": 10,
"reglas": [
"Dos equipos A son ogros y B humanos; los primeros atrapan humanos, éstos para evitarlo pueden decir la palabra ¡Gigantes!",
"Y pararse con las piernas abiertas y brazos en cruz, siendo salvados de ésta posición si alguien les pasa por abajo.",
"También podrán decir ¡Enanos; y agacharse en bolita para que sean salvados saltándolos.",
"Quienes son capturados se sientan y esperan a que atrapen a todos o se termine el tiempo para cambiar roles."
],
