"mat": [
"cuerdas"
],
"min": 10,
"reglas": [
"En parejas deberán trazar 3 líneas usando las cuerdas frente a frente, el maestro dará indicaciones de como desplazarse, es decir: “Saltar en un pie hacía la línea 2, saltar lo más rápido a la línea 3” haciendo que los alumnos vayan a la par tocando dedo índice con dedo índice de ambos alumnos y sin despegarlos durante todo su trayecto.",
"Cuando el maestro indique “vara alta” deberán estirar sus brazos hacia arriba, cuando diga “vara chica” deberán ponerse en cuclillas."
],
