"mat": [
"conos",
"cuerdas"
],
"min": 10,
"reglas": [
"Los alumnos se colocan en parejas formando dos círculos concéntricos.",
"Cada uno de éstos se mueve en sentido contrario.",
"A la señal cada jugador del equipo interior intenta atrapar a su adversario del equipo exterior que se escapa.",
"El tiempo disponible es de diez segundos que el profesor cuenta en voz alta.",
"Se contabilizan los atrapados que son puntos para el equipo y se cambian los roles.",
"Acostados en el suelo boca arriba flexionar una rodilla y con las manos entrelazadas rodearla y jalar hacia arriba.",
"Primero derecha, después izquierda y finalmente las dos al mismo tiempo | Cuerdas Conos."
],
