"reglas": [
"Los alumnos se desplazan caminando, trotando o corriendo, el profesor da un número de silbatazos y es la cantidad de personas con las que tiene que desplazarse, cuando da una palmada todos deben de colocarse en una cruz y colocarse en puntos de apoyo de acuerdo a la cantidad de integrantes. 1, 2, 3 cámara, acción: Escenificar una carrera hacia el salón de clases pero todos los movimientos deben ser en cámara lenta. | Boliche Pelotas."
],
