"min": 10,
"reglas": [
"El alumno se desplaza sobre su espacio y al silbatazo deberán realizar saltos elevando rodillas lo más alto que puedan, al tocar el suelo realizarán abanico (consiste en extender sus brazos y moverse con rodillas flexionadas) y así deberán realizarlo 10 veces cada ejercicio."
],
