"reglas": [
"4 equipos y se coloca cada uno formado en filas en un extremo de la cancha quedando de frente a un equipo.",
"Al centro de la cancha se pondrán 2 conos con un paliacate encima cada uno.",
"A la señal los primeros de cada fila deberán de correr lo más rápido para ganar el paliacate.",
"Se proponen diferentes formas de desplazamiento o acciones motrices a realizar antes de salir corriendo."
],
