"A su vez todas corren intentando no ser tocadas.",
"Cuando una persona toca a otra, una agarra a la otra por la cintura y siguen corriendo juntas como el tren chucu intentando tocar a alguien más e intentando que nadie les toque.",
"Si tocan a alguien más, habrán de añadirse al grupo formando un nuevo trenecito chucu que en esta ocasión será de tres o más personas.",
"La que va delante pilla (intenta tocar a alguien).",
"Las otras colaboran para que la última no sea tocada.",
