"El que consiga parar más será el que empiece.",
"Se tiran las tapas al suelo y sin tocarlas de cómo han caído, se toma una, se tira hacia arriba, ésta no puede caer al suelo, y así sucesivamente, se van tirando hasta que las ha tomado todas.",
