"est": "Manipulación de objetos",
"hab": [],
"plano": "circulo",
"mat": [
"pelotas"
],
"min": 10,
"reglas": [
"Se forman equipos en hileras, situados detrás de una línea de lanzamiento.",
"Frente a cada hilera y a una distancia determinada por el profesor se sitúan tres bolos en forma de triángulo, cada uno dentro de un pequeño círculo.",
"Un niño se ubica detrás de los bolos; el primer alumno de cada equipo tendrá una pelota en sus manos.",
"A la señal, los niños que tienen las pelotas, la lanzan en dirección a los bolos.",
"El niño que se encontraba detrás, recoge la pelota, sale corriendo y se la entrega al primer alumno de la hilera, incorporándose al final de la misma.",
"Cada bolo derribado vale un punto; ganará el equipo que más puntos acumule."
],
