"Los jugadores que han sido tocados se transforman en policías que intentarán no dejar pasar a por balones a los demás.",
"Cuando haya muchos policías, se puede limitar su manera de moverse para prolongar el juego.",
"Acostados boca abajo en círculo tocando hombro con hombro y manos en la espalda.",
"Se coloca un globo al centro y deben soplar tratando de que éste toque la cara de un compañero."
