"A la señal los leones tendrán que atrapar a los canguros, cuando esto pase se convertirá en leones.",
"Así sucesivamente hasta que atrapen a todos y se cambia de roles.",
"En parejas uno acostado y el otro le coloca un cuadro de papel en el abdomen o pecho de acuerdo al tipo de respiración y observa como sube y baja. | Hojas de papel Conos."
