"min": 10,
"reglas": [
"Todos se ubican sentados en círculo; en el centro dos niños con los ojos tapados; una es la “lluvia” y la otra la “mariposa”.",
"El objetivo del juego es que la lluvia atrape a la mariposa.",
"Los niños que están sentados en el círculo les ayudarán de la siguiente forma: cuando la lluvia está lejos de la mariposa, los niños golpean lentamente con sus pies el piso, cuando la lluvia se acerca a la mariposa golpean rápidamente el piso para hacerle saber a la mariposa que la lluvia está cerca."
],
