"min": 10,
"reglas": [
"Toda la clase se coloca en círculo; un alumno es el director de orquesta y debe marcar un ritmo determinado utilizando varias partes del cuerpo.",
"Todos los demás alumnos tienen que realizar los mismos movimientos y el mismo ritmo.",
"Un compañero que se coloca en el centro del círculo, y que no sabe quién es el director de orquesta, tiene que descubrirlo.",
"Si no lo descubre cuando para la música le tapan los ojos y deben asignar nuevo director.",
"Solo podrá cambiar de rol hasta adivinar. | Conos Pelotas Pañuelos."
],
