/* Materiales que usan los juegos de la comunidad (se agregan a la lista de Tlamatini si no estaban) */
[['platillos', 'Platillos'], ['colchonetas', 'Colchonetas o tapetes'], ['paracaidas', 'Paracaídas'], ['zancos', 'Zancos'], ['botellas', 'Botellas de plástico'], ['hojas', 'Hojas de periódico o cartón'], ['bastones', 'Bastones o palos de escoba'], ['frisbis', 'Frisbis'], ['vallas', 'Vallas']]
  .forEach(m => { if (!EF_MAT.some(x => x[0] === m[0])) EF_MAT.push(m); });
Object.assign(EF_SUST, { platillos: 'tapas grandes o círculos de cartón', colchonetas: 'cartones grandes o costales rellenos', paracaidas: 'una sábana vieja o lona', zancos: 'botes de lata con cordón', botellas: 'envases de jugo o leche', hojas: 'cartón de cajas', bastones: 'periódico enrollado con cinta', frisbis: 'platos desechables resistentes', vallas: 'cuerdas entre dos conos o mochilas' });
Object.assign(EST_COL, { 'Persecución': '#8A4B14', 'Relevos': '#0E6E7E', 'Expresión corporal': '#9A3B6B', 'Manipulación de objetos': '#3F6E2A', 'Equilibrio': '#5A5FA8', 'Cuento motor': '#B0563A', 'Juego motor': '#4D6A60', 'Cooperativo': EST_COL['Cooperativo'] || '#1B7560', 'Circuito de acción motriz': EST_COL['Circuito de acción motriz'] || '#4F7FB8' });
